head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil21200";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil21200.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + " 페이지) "; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_currentPageSize_onchange
 * @description slc_currentPageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_currentPageSize_onchange = async function(e){
    try {
        await scwin.search();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil21200.slc_currentPageSize_onchange' }); }
};

/**
 * @method
 * @name grd_irDisclsList_oncellclick
 * @description grd_irDisclsList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_irDisclsList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_irDisclsList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_irDisclsList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["regStatCd"] === '0') { await scwin.goWrite(r["acptNo"], "1"); return; }
        if (r["regStatCd"] === '1') { await scwin.goWrite(r["acptNo"], "2", r["resoroomId"]); return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_irDisclsList.oncellclick' });
    }
};

/**
 * @method
 * @name krxpage_pagenavigator_84_onclick
 * @description krxpage_pagenavigator_84 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_84_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_loadListReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_84.page' }); } await scwin.tx_load_list(); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/company/irData.do?method=searchIRDiscls",
        ref: "dma_SearchReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_goWrite
 * @description go Write 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goWrite = async function () {
    const sbmOptions = {
        id: "tx_fn_goWrite",
        method: "post",
        action: "/company/irData.do",
        ref: "dma_goWriteReq",
        target: "dlt_irDisclsList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/company/irData.do?method=searchIRDiscls",
        ref: "dma_loadListReq",
        target: "dlt_irDisclsList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil21200.tx_load_list" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] !== null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot !== null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_84").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_irDisclsList_fmt_irHldDd
 * @description grd ir Discls List fmt ir Hld Dd 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_irDisclsList_fmt_irHldDd = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_irDisclsList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "regStatCd") ?? '') : '');
        if (v === '0') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "irHldDd") : '') ?? '') + '</a>'; }
        if (v === '1') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "irHldDd") : '') ?? '') + '</a>'; }
        return String((dl && dl.getCellData ? dl.getCellData(r, "irHldDd") : '') ?? '');
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_irDisclsList.irHldDd" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_irDisclsList_fmt_column6
 * @description grd ir Discls List fmt column6 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_irDisclsList_fmt_column6 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_irDisclsList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "regStatCd") ?? '') : '');
        if (v === '1') { return "임시저장"; }
        if (v === '2') { return "제출완료"; }
        if (v === '3') { return "승인"; }
        return "미작성";
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_irDisclsList.column6" }); return String(data ?? ''); }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    $c.util.getComponent("dma_SearchReq").set("action", '/company/irDiscls.do');
    $c.util.getComponent('dma_SearchReq').set('method', 'searchIRDiscls');
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name goWrite
 * @description go Write 처리
 * @param {*} acptNo acptNo
 * @param {String} statTpCd statTpCd
 * @param {String} resoroomId resoroomId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goWrite = async function (acptNo, statTpCd, resoroomId) {
    (document.irDisclsForm || { elements: [] }).action = '/company/irData.do';
    $c.util.getComponent('dma_SearchReq').set('method', 'applIRData');
    $c.util.getComponent('dma_SearchReq').set('acptNo', acptNo);
    $c.util.getComponent('dma_SearchReq').set('statTpCd', statTpCd);
    if (statTpCd === '2') {
        $c.util.getComponent('dma_SearchReq').set('resoroomId', resoroomId);
    }
    const nr = await scwin.tx_fn_goWrite();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil21212/jldfil21212.xml", { "method": 'applIRData', "acptNo": acptNo, "statTpCd": statTpCd, "resoroomId": resoroomId });
    }
};
